package dev.veld.jetbrains

import com.intellij.openapi.application.PathManager
import org.jetbrains.plugins.textmate.api.TextMateBundleProvider
import java.io.IOException
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.StandardCopyOption

/** Registers the Veld TextMate grammar (generated by `cargo xtask codegen`) for highlighting. */
class VeldTextMateBundleProvider : TextMateBundleProvider {
    override fun getBundles(): List<TextMateBundleProvider.PluginBundle> {
        val dir = extract() ?: return emptyList()
        return listOf(TextMateBundleProvider.PluginBundle("Veld", dir))
    }

    private fun extract(): Path? = try {
        val target = PathManager.getSystemDir().resolve("veld-textmate")
        for (name in FILES) {
            val stream = VeldTextMateBundleProvider::class.java.getResourceAsStream("/textmate/veld/$name") ?: return null
            val out = target.resolve(name)
            Files.createDirectories(out.parent)
            stream.use { Files.copy(it, out, StandardCopyOption.REPLACE_EXISTING) }
        }
        target
    } catch (_: IOException) {
        null
    }

    private companion object {
        val FILES = listOf("package.json", "language-configuration.json", "syntaxes/veld.tmLanguage.json")
    }
}
